    set_data(
        &mut store,
        &issue_id,
        "config",
        "schema:1",
        &serde_json::json!({"key": "value"}),
    )
    .unwrap();
    assert_eq!(max_sequence(&mut store), before + 1);

    // Changed value does advance it
    set_data(
        &mut store,
        &issue_id,
        "config",
        "schema:1",
        &serde_json::json!({"key": "changed"}),
    )
    .unwrap();
    assert_eq!(max_sequence(&mut store), before + 2);

